pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "Test", "TST"); }
    function testFuzz_property(uint256 burnAmount) public {
        // constrain burn amount to avoid underflow in the reference, keeping domain wide enough to trigger the bug
        uint256 ownerBalance = c.balanceOf(address(this));
        vm.assume(burnAmount <= ownerBalance);
        // ensure burn amount is at least 1 so totalSupply actually changes in the reference
        vm.assume(burnAmount > 0);

        // compute total supply and balance sum before burn
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 sumBalanceBefore = c.balanceOf(address(this));

        c.burn(burnAmount);

        // compute total supply and balance sum after burn
        uint256 totalSupplyAfter = c.totalSupply();
        uint256 sumBalanceAfter = c.balanceOf(address(this));

        // In the reference, totalSupply change equals sum of balance changes
        // i.e. (totalSupplyBefore - totalSupplyAfter) == (sumBalanceBefore - sumBalanceAfter)
        // But the bug makes totalSupply decrease without decreasing any balance, so this equality breaks.
        assertTrue(totalSupplyBefore - totalSupplyAfter == sumBalanceBefore - sumBalanceAfter);
    }
}

