        // totalSupply and owner balance must be >= burnAmount to avoid underflow in the reference
        initialMint = bound(initialMint, 1, type(uint256).max - 1);
        burnAmount = bound(burnAmount, 1, type(uint256).max - 1);
        vm.assume(initialMint >= burnAmount);

        // Setup: mint tokens to owner so they have enough to burn without underflow
        vm.prank(address(this)); // setUp runs as the test contract, which is the owner of c
        c.mintToken(address(this), initialMint);

        uint256 supplyBefore = c.totalSupply();

        vm.prank(address(this));
        c.burn(burnAmount);

        uint256 supplyAfter = c.totalSupply();

        // General rule: if the owner had enough balance (ensured above), the totalSupply
        // must decrease by exactly burnAmount. The buggy version (without balance check)
        // can cause totalSupply to underflow (wrap) and break this decrement correspondence.
        assertTrue(supplyAfter == supplyBefore - burnAmount);
