contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        // Admissible domain: burnAmount can be any uint256, including values larger than totalSupply
        vm.assume(burnAmount > 0);
        // Ensure owner has some balance to attempt burn
        vm.prank(address(c).call(abi.encodeWithSignature("owner()")));
        // Actually set up: mint some tokens to owner so we can burn
        // First, we need to make the owner call mintToken. But setUp deploys with 0, owner has 0.
        // We can just prank the owner and call mintToken.
        address owner = c.owner();
        vm.prank(owner);
        c.mintToken(owner, type(uint256).max);
        // Now attempt burn with a very large amount that could cause underflow
        vm.prank(owner);
        c.burn(burnAmount);
        // After burn, totalSupply must be a valid uint256 (non-negative by definition, but underflow wraps to huge)
        // The reference contract will revert when burnAmount > balance, so we use try/catch to capture revert.
        // But we already called burn above. We need to assert after the call.
        // Since the correct contract reverts on insufficient balance, a successful call indicates underflow in mutant.
        // To make the assertion work for both, we observe totalSupply >= 0 which is always true for uint256, but we need to detect underflow.
        // Instead, we check that after the call, totalSupply has not increased beyond the minted amount? That's not simple.
        // Let's use try/catch:
        // Actually, we'll structure differently: we call burn in try/catch, and assert that if it succeeded, totalSupply is still <= original totalSupply (which was max). But underflow makes it > max? No, underflow wraps to huge number from 0.
        // Wait, correct approach: assertTrue that after the call, the invariant holds that totalSupply never exceeds the initial minted amount (type(uint256).max) by more than the burned? No.
        // Simplest: the correct contract always reverts when burnAmount > balance, so any non-reverting call is a bug. We assert that the call did not revert.
        // But we need an assertion that passes for reference and fails for mutant.
        // For reference: burn reverts (if burnAmount > 0? we minted max, so any burn > 0 would succeed unless we exceed balance? Actually we minted max to owner, so owner has max balance. Any burn <= max succeeds. So both contracts succeed for burn <= max. For burn > max, reference reverts, mutant succeeds (underflows).
        // So we need to assert something like: if burn succeeds, totalSupply <= max? No, underflow on mutant would make totalSupply huge > max.
        // Better: assert that after burn, totalSupply does not equal a value that indicates underflow. But we can just assert totalSupply <= originalTotalSupply? That would fail for reference when it succeeds (because it decreased), but passes for mutant when burnAmount > balance (underflows, totalSupply becomes huge > original). So that works.
        // Let's capture original totalSupply before burn.
    }
}

